/* ========= CONFIGURAÇÃO DO BANCO DE DADOS =========
 backend:'mysql' -> conversa com a API (proz-backend/server.js), que grava no MySQL.
 backend:'local' -> localStorage, só para demonstração.
 Em url coloque o endereço da API (ex.: https://api.meu-hospital.com), só usado com backend:'mysql'. */
const CFG={backend:'local',url:''};
const OK=()=>CFG.backend==='mysql';
const K='prontuario_psiq_db';let db={pts:[],log:[]},TOKEN=null;
const rest=(path,m='GET',b)=>fetch(CFG.url+'/api/'+path,{method:m,headers:{'Content-Type':'application/json',Authorization:'Bearer '+TOKEN},body:b?JSON.stringify(b):undefined}).then(r=>{if(!r.ok)throw new Error(r.status);return r.json()});
const API={
 async load(){
  if(!OK()){try{return JSON.parse(localStorage.getItem(K))||{pts:[],log:[]}}catch(e){return{pts:[],log:[]}}}
  const[a,b]=await Promise.all([rest('prontuarios'),rest('auditoria')]);return{pts:a,log:b}},
 async savePt(p){if(!OK())return this.local();await rest('prontuarios/'+p.id,'PUT',p)},
 async addLog(l){if(!OK())return this.local();await rest('auditoria','POST',l)},
 local(){try{localStorage.setItem(K,JSON.stringify(db))}catch(e){}}
};
const sync=async fn=>{try{await fn()}catch(e){alert('Falha ao salvar no banco de dados: '+e.message)}};

/* ========= APLICAÇÃO ========= */
const USERS=[{reg:'CRM 65432',p:'1234',nome:'Dr. Rafael Mendes',role:'Médico'},{reg:'COREN 123456',p:'1234',nome:'Ana Souza',role:'Técnico'}];
const normReg=x=>String(x||'').toUpperCase().replace(/[^A-Z0-9]/g,''),roleLbl=r=>r==='Técnico'?'Técnico de Enfermagem':r;
const isMed=()=>me&&me.role==='Médico';
let me=null,pid=null,tab='inicio',q='';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nowIn=()=>new Date(Date.now()-new Date().getTimezoneOffset()*6e4).toISOString().slice(0,16);
const fmt=t=>{try{return new Date(t).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}catch(e){return t}};
const fd=d=>d?d.split('-').reverse().join('/'):'-';
const age=d=>d?Math.floor((Date.now()-new Date(d))/31557600000):'';
const who=()=>({by:me.nome,reg:me.reg,role:me.role});
const P=()=>db.pts.find(p=>p.id===pid);
const num=p=>'#'+String(db.pts.indexOf(p)+1).padStart(5,'0');
function log(p,acao){const l={ts:new Date().toISOString(),pid:p.id,nome:p.nome,acao,...who()};db.log.push(l);sync(()=>API.addLog(l))}
const persist=p=>sync(()=>API.savePt(p));
const go=(t,id)=>{tab=t;if(id)pid=id;view()};
const heart='<svg viewBox="0 0 40 40"><path d="M20 35S4 25 4 14a8 8 0 0 1 16-2 8 8 0 0 1 16 2c0 11-16 21-16 21z" fill="#fff"/><path d="M20 12v14M13 19h14" stroke="#4a62ad" stroke-width="4"/></svg>';
function modal(html,fn){const d=$('#dlg');d.innerHTML=html;d.showModal();d.querySelector('form').onsubmit=e=>{e.preventDefault();fn(Object.fromEntries(new FormData(e.target)));d.close()};d.querySelector('[data-x]').onclick=()=>d.close()}
const foot='<div style="display:flex;gap:8px;margin-top:14px"><button class="btn">Salvar</button><button type="button" class="btn o" data-x>Cancelar</button></div>';

const svg=(d,c='')=>`<svg ${c?`class="${c}" `:''}viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg>`;
const IC={id:'<rect x="3" y="5" width="18" height="14" rx="3"/><circle cx="9" cy="11" r="2"/><path d="M6.5 16c.6-1.4 1.6-2 2.5-2s1.9.6 2.5 2M14 10h4M14 14h3"/>',lock:'<rect x="5" y="11" width="14" height="9" rx="3"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/>',eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',go:'<path d="M5 12h14M13 6l6 6-6 6"/>',ok:'<path d="M5 12.5l4.5 4.5L19 7.5"/>',shield:'<path d="M12 3l7 3v5c0 4.500-3 8-7 10-4-2-7-5.500-7-10V6z"/>'};

/* ===== LOGIN E NAVEGAÇÃO ===== */
function loginView(){return `<div class="login"><section class="l-hero"><div class="l-brand">${heart}<span>PROZ<br>CENTER</span></div>
<div class="l-copy"><h1>Prontuário psiquiátrico, claro e <em>rastreável</em>.</h1><p>Pacientes, prontuários, medicação e evolução de enfermagem em um só lugar, com a autoria de cada registro sempre identificada.</p></div>
<ul class="l-feat"><li><i>${svg(IC.ok)}</i>Evolução de enfermagem integrada ao prontuário</li><li><i>${svg(IC.ok)}</i>Controle de medicação por paciente</li><li><i>${svg(IC.ok)}</i>Autoria registrada em cada anotação</li></ul>
<div class="l-mark">${heart}</div></section>
<main class="l-pane"><div class="l-card"><h2>Acesse com seu registro profissional</h2><p class="l-sub">Entre com o seu conselho, número de registro e senha.</p>
<form name="lf" onsubmit="login(this);return false"><div class="seg" role="radiogroup" aria-label="Conselho profissional" onchange="ph(event.target.value)"><label><input type="radio" name="c" value="CRM" checked><span>CRM<small>Médico</small></span></label><label><input type="radio" name="c" value="COREN"><span>COREN<small>Enfermagem</small></span></label></div>
<div class="fld"><label for="lu">Nº do registro</label>${svg(IC.id,'ic')}<input id="lu" name="u" placeholder="Ex.: 65432" inputmode="numeric" autocomplete="username" required></div>
<div class="fld"><label for="lp">Senha</label>${svg(IC.lock,'ic')}<input id="lp" name="p" type="password" placeholder="Digite sua senha" autocomplete="current-password" required><button type="button" class="eye" aria-label="Mostrar senha" onclick="eye(this)">${svg(IC.eye)}</button></div>
<p id="err" class="l-err" role="alert"></p><button class="btn l-go">Entrar ${svg(IC.go)}</button></form>
<div class="l-demo"><p>Demonstração · senha 1234</p><div><button type="button" onclick="demo('CRM','65432')"><b>Médico</b><span>CRM 65432</span></button><button type="button" onclick="demo('COREN','123456')"><b>Téc. de Enfermagem</b><span>COREN 123456</span></button></div></div>
<p class="l-note">${svg(IC.shield)}Acesso restrito. Cada ação fica registrada com autoria.</p></div></main></div>`}
function eye(b){const i=b.parentNode.querySelector('input'),show=i.type==='password';i.type=show?'text':'password';b.setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha');b.classList.toggle('on',show)}
function ph(c){$('#lu').placeholder='Ex.: '+(c==='CRM'?'65432':'123456')}
function demo(c,u){const f=document.forms.lf;f.c.value=c;ph(c);f.u.value=u;f.p.value='1234';$('#err').textContent='';f.p.focus()}
function menu(o){const b=document.body,open=o===undefined?!b.classList.contains('menu-open'):o;b.classList.toggle('menu-open',open);const x=$('#burger');if(x)x.setAttribute('aria-expanded',String(open));if(open){const n=$('.nav.on')||$('.nav');n&&n.focus({preventScroll:true})}else if(x&&o===false&&document.activeElement&&document.activeElement.closest&&document.activeElement.closest('.side'))x.focus()}
addEventListener('keydown',e=>{if(e.key==='Escape')menu(false)});matchMedia('(min-width:901px)').addEventListener('change',e=>{if(e.matches)menu(false)});

/* ===== RENDERIZAÇÃO DA INTERFACE ===== */
function view(){
 document.body.classList.remove('menu-open');A11.stop();window.scrollTo(0,0);
 if(!me){A11.stop();$('#app').innerHTML=loginView();A11.syncFab();return}
  const nav=isMed()?[['inicio','🏠','Início'],['pacientes','👥','Pacientes'],['prontuarios','📄','Prontuários'],['enfermagem','🩺','Enfermagem (consulta)'],['setembro','🎗️','Setembro Amarelo'],['acess','♿','Acessibilidade'],['config','⚙️','Configurações']]:[['inicio','🏠','Início'],['enfermagem','🩺','Evolução do paciente'],['pacientes','👥','Pacientes'],['prontuarios','📄','Prontuários'],['setembro','🎗️','Setembro Amarelo'],['acess','♿','Acessibilidade'],['config','⚙️','Configurações']];
  const t=GRUPO[tab]||tab;
 $('#app').innerHTML=`<div class="app"><div class="scrim" onclick="menu(false)"></div><nav class="side" id="menu" aria-label="Menu principal"><div class="brand">${heart}<span>PROZ<br>CENTER</span><button type="button" class="side-x" aria-label="Fechar menu" onclick="menu(false)">✕</button></div>${nav.map(n=>`<button class="nav ${t===n[0]?'on':''}" onclick="go('${n[0]}')">${n[1]} ${n[2]}</button>`).join('')}<div class="side-me"><b>${esc(me.nome)}</b>${esc(roleLbl(me.role))} · ${esc(me.reg)}</div></nav><main class="main"><div class="bar"><button type="button" class="burger" id="burger" aria-label="Abrir menu" aria-controls="menu" aria-expanded="false" onclick="menu()"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button>${['pacientes','prontuarios'].includes(tab)?`<input class="search" placeholder="Buscar paciente, prontuário, nº de atendimento..." value="${esc(q)}" oninput="busca(this.value)">`:''}<div class="me"><b>${esc(me.nome)}</b>${esc(roleLbl(me.role))} · ${esc(me.reg)}</div></div><div id="pg">${page()}</div></main></div>`;A11.syncFab();}
function cardify(root){root.querySelectorAll('table:not([data-r])').forEach(t=>{t.setAttribute('data-r','1');const rows=[...t.querySelectorAll('tr')];let hs=[];rows.forEach(r=>{if(r.querySelector('th')){r.classList.add('hd');hs=[...r.children].map(c=>c.textContent.trim());return}let i=0;[...r.children].forEach(td=>{td.setAttribute('data-label',td.colSpan>1?'':(hs[i]||''));i+=td.colSpan||1;if(!td.querySelector(':scope>.tv')){const w=document.createElement('div');w.className='tv';while(td.firstChild)w.appendChild(td.firstChild);td.appendChild(w)}})})})}
new MutationObserver(()=>cardify(document)).observe(document.body,{childList:true,subtree:true});
function busca(v){q=v;if(['pacientes','prontuarios'].includes(tab))$('#pg').innerHTML=page()}
function page(){return({inicio,pacientes,prontuarios,prontuario,evolucao,enfermagem,enf,enfnova,setembro,acess,config})[tab]()}
async function login(f){const d=new FormData(f),id=normReg(d.get('c')+d.get('u')),p=d.get('p');
 try{if(OK()){const r=await fetch(CFG.url+'/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({u:id,p})});if(!r.ok)throw 0;const j=await r.json();TOKEN=j.token;me=j.user}
 else{const x=USERS.find(x=>normReg(x.reg)===id&&x.p===p);if(!x)throw 0;me=x}
 db=await API.load();ensureDemo()}catch(e){$('#err').textContent=OK()?'Registro ou senha inválidos, ou servidor indisponível.':'Registro ou senha inválidos.';return false}
 tab='inicio';view();return false}

/* ===== DETALHES DO PRONTUÁRIO ===== */
function prontuario(){const p=P();if(!p)return prontuarios();const v=p.vitais||{},ob=p.status==='Óbito',lk=ob?'disabled':'';
 return `${ob?'<div class="ob">Paciente em óbito — registros bloqueados.</div>':''}
 <h2><span style="font-size:20px">Prontuário ${num(p)}</span><span><button class="btn o s" onclick="go('prontuarios')">Voltar</button> <button class="btn ${podeEnf()?'':'o '}s" onclick="go('enf')">${podeEnf()?'Evolução de enfermagem':'Ver evolução de enfermagem'}</button> ${isMed()?`<button class="btn s" ${lk} onclick="go('evolucao')">Nova anotação clínica</button>`:''}</span></h2>
 <div class="card"><h2><span style="font-size:18px">${esc(p.nome)}</span><span class="tag ${ob?'x':''}">${esc(p.status)}</span></h2>
 <div class="row" style="grid-template-columns:repeat(4,1fr)"><div><span class="by">Sexo</span><br>${esc(p.sexo)}</div><div><span class="by">Nascimento</span><br>${fd(p.nasc)} (${age(p.nasc)} anos)</div><div><span class="by">Leito</span><br>${esc(p.leito)}</div><div><span class="by">Alergias</span><br><span class="${p.alergias?'alert':''}">${esc(p.alergias||'Nenhuma informada')}</span></div></div>
 <p><span class="by">Motivo da internação</span><br>${esc(p.motivo)}</p><p class="by">Prontuário criado por ${esc(p.criado.by)} (${esc(p.criado.reg)}) em ${fmt(p.criado.ts)}</p></div>
 <div class="g2"><div>
 <div class="card"><h2>Sinais vitais <button class="btn s" ${lk} onclick="vit()">Registrar</button></h2><div class="vit"><div><span>PA</span><b>${esc(v.pa||'-')}</b></div><div><span>FC (bpm)</span><b>${esc(v.fc||'-')}</b></div><div><span>FR (irpm)</span><b>${esc(v.fr||'-')}</b></div><div><span>SpO₂ (%)</span><b>${esc(v.spo2||'-')}</b></div><div><span>Temp (°C)</span><b>${esc(v.temp||'-')}</b></div><div><span>Dor (0-10)</span><b>${esc(v.dor||'-')}</b></div></div><p class="by">${v.ts?`Última aferição: ${fmt(v.ts)} por ${esc(v.by)} (${esc(v.reg)})`:'Sem registro'}</p></div>
 <div class="card"><h2>Medicação ${isMed()?`<button class="btn s" ${lk} onclick="med()">Prescrever</button>`:''}</h2><div class="tw"><table><tr><th>Medicamento</th><th>Dose</th><th>Via</th><th>Horário</th><th>Prescrito por</th><th>Administração</th></tr>${(p.meds||[]).map((m,mi)=>`<tr><td>${esc(m.med)}<div class="by">${esc(m.obs)}</div></td><td>${esc(m.dose)}</td><td>${esc(m.via)}</td><td>${esc(m.hor)}</td><td class="by">${esc(m.by)} (${esc(m.reg)})<br>${fmt(m.ts)}</td><td class="by">${(m.adm&&m.adm.length)?'Última: '+fmt(m.adm[m.adm.length-1].ts)+'<br>'+esc(m.adm[m.adm.length-1].by):'Ainda não administrada'}${podeEnf()&&!ob?`<br><button class="btn o s" onclick="admMed(${mi})">Registrar administração</button>`:''}</td></tr>`).join('')||'<tr><td colspan=6 class="by">Nenhuma medicação prescrita.</td></tr>'}</table></div></div></div>
 <div><div class="card"><h2>Anotações clínicas</h2>${(p.notas||[]).slice().reverse().map(n=>`<div class="note"><b>${fmt(n.dh)}</b> ${n.obito?'<span class="tag x">ÓBITO</span>':''}<div class="by">Motivo da internação: ${esc(n.motivo)}</div><p>${esc(n.texto)}</p><div class="by">Registro técnico: ${esc(n.by)} — ${esc(n.reg)}</div></div>`).join('')||'<p class="by">Nenhuma anotação registrada.</p>'}</div>
 <div class="card"><h2>Evolução de enfermagem <button class="btn o s" onclick="go('enf')">Abrir</button></h2>${(p.enf||[]).slice().sort((a,b)=>new Date(b.dh)-new Date(a.dh)).slice(0,2).map(evHtml).join('')||'<p class="by">Nenhuma evolução de enfermagem.</p>'}</div><div class="card"><h2>Histórico de alterações</h2><div class="tw"><table><tr><th>Quando</th><th>Quem</th><th>Ação</th></tr>${db.log.filter(l=>l.pid===p.id).slice().reverse().map(l=>`<tr><td>${fmt(l.ts)}</td><td>${esc(l.by)}<div class="by">${esc(l.role)} · ${esc(l.reg)}</div></td><td>${esc(l.acao)}</td></tr>`).join('')}</table></div></div></div></div>`}

function evolucao(){const p=P();if(!p||p.status==='Óbito'||!isMed())return prontuario();
 return `<h2><span style="font-size:20px">Nova anotação clínica</span></h2><p class="sub">${esc(p.nome)} · Prontuário ${num(p)}</p>
 <form class="card" onsubmit="return saveNota(this)"><div class="row"><div><label>Data e hora *</label><input type="datetime-local" name="dh" value="${nowIn()}" required></div><div><label>Registro técnico</label><input value="${esc(me.nome+' — '+me.reg)}" readonly></div></div>
 <label>Motivo da internação *</label><input name="motivo" value="${esc(p.motivo)}" required><label>Anotação *</label><textarea name="texto" rows="8" required></textarea>
 <label style="display:flex;gap:8px;align-items:center;color:var(--red)"><input type="checkbox" name="obito" value="1" style="width:auto"> Informar óbito do paciente</label>
 <div style="display:flex;gap:8px;margin-top:14px"><button class="btn">Registrar evolução</button><button type="button" class="btn o" onclick="go('prontuario')">Cancelar</button></div></form>`}
function saveNota(f){if(!isMed())return false;const d=Object.fromEntries(new FormData(f)),p=P(),ob=!!d.obito;
 p.notas.push({dh:d.dh,motivo:d.motivo,texto:d.texto,obito:ob,ts:new Date().toISOString(),...who()});if(ob)p.status='Óbito';
 log(p,ob?'Informou ÓBITO em anotação':'Adicionou anotação clínica');persist(p);go('prontuario');return false}

function setembro(){return `<h1>Setembro Amarelo</h1><p class="sub">Mês de prevenção ao suicídio</p><div class="g2"><div class="card" style="padding:0;overflow:hidden"><img src="setembro-amarelo.jpg" alt="Cartaz Setembro Amarelo: como ajudar" style="display:block;width:100%;height:auto"></div>
 <div class="card"><h2>Se precisar de ajuda</h2><p><b>CVV (Centro de Valorização da Vida): ligue 188.</b> Atendimento gratuito, sigiloso, feito por voluntários, 24 horas por dia em todo o país. Também há chat e e-mail pelo site oficial.</p><p><b>SAMU: ligue 192</b> em caso de emergência médica grave ou risco imediato.</p></div></div>`}

/* ===== SINAIS VITAIS E MEDICAÇÕES ===== */
function vit(){const v=P().vitais||{};modal(`<form><h2>Registrar sinais vitais</h2><div class="row"><div><label>PA</label><input name="pa" value="${esc(v.pa)}"></div><div><label>FC (bpm)</label><input name="fc" value="${esc(v.fc)}"></div><div><label>FR (irpm)</label><input name="fr" value="${esc(v.fr)}"></div><div><label>SpO₂ (%)</label><input name="spo2" value="${esc(v.spo2)}"></div><div><label>Temperatura (°C)</label><input name="temp" value="${esc(v.temp)}"></div><div><label>Dor (0-10)</label><input name="dor" value="${esc(v.dor)}"></div></div>${foot}</form>`,d=>{const p=P();p.vitais={...d,ts:new Date().toISOString(),...who()};log(p,'Atualizou sinais vitais');persist(p);view()})}
function admMed(i){const p=P(),m=p&&p.meds[i];if(!m||!podeEnf()||p.status==='Óbito')return;if(!confirm('Confirmar administração de '+m.med+' '+m.dose+' agora?'))return;(m.adm=m.adm||[]).push({ts:new Date().toISOString(),...who()});log(p,'Administrou medicação: '+m.med+' '+m.dose);Promise.resolve(persist(p)).finally(view)}
function med(){if(!isMed())return;modal(`<form><h2>Prescrever medicação</h2><label>Medicamento *</label><input name="med" required><div class="row"><div><label>Dose *</label><input name="dose" required></div><div><label>Via</label><select name="via"><option>VO</option><option>IM</option><option>EV</option><option>SC</option></select></div></div><label>Horário</label><input name="hor" placeholder="ex.: 8h/20h"><label>Observação</label><input name="obs">${foot}</form>`,d=>{const p=P();p.meds.push({...d,ts:new Date().toISOString(),...who()});log(p,'Prescreveu medicação: '+d.med+' '+d.dose);Promise.resolve(persist(p)).finally(view)})}

/* ========= NOVOS RECURSOS: Enfermagem, Pacientes x Prontuários, pacientes fictícios ========= */
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim();
const loc=ms=>new Date(ms-new Date(ms).getTimezoneOffset()*6e4).toISOString().slice(0,16);
const turnoDe=x=>{const h=new Date(x).getHours();return h>=7&&h<13?'Manhã':h>=13&&h<19?'Tarde':'Noite'};
const tkey=x=>{const d=new Date(x);if(d.getHours()<7)d.setDate(d.getDate()-1);return d.toDateString()+turnoDe(x)};
const ENF=['Técnico'],podeEnf=()=>ENF.includes(me.role);
const isDemo=p=>String(p.id).startsWith('demo'),demoTag=p=>isDemo(p)?'<span class="tag d">DEMO</span>':'';
const lastEnf=p=>(p.enf||[]).reduce((a,e)=>!a||new Date(e.dh)>new Date(a.dh)?e:a,null);
const doneNow=p=>(p.enf||[]).some(e=>tkey(e.dh)===tkey(Date.now()));
const RK={Alto:3,Moderado:2,Baixo:1},RT={Alto:'x',Moderado:'w',Baixo:''};
const risco=p=>(lastEnf(p)||{}).risco||'';
const rtag=r=>r?`<span class="tag ${RT[r]}">Risco ${esc(r)}</span>`:'<span class="tag g">Sem avaliação</span>';
const porLeito=(a,b)=>String(a.leito).localeCompare(String(b.leito),'pt',{numeric:true});
const achar=p=>norm(p.nome+' '+p.leito+' '+num(p)+' '+p.motivo).includes(norm(q));
const LISTAS=['pacientes','prontuarios','enfermagem'],GRUPO={prontuario:'prontuarios',evolucao:'prontuarios',enf:'enfermagem',enfnova:'enfermagem'};
let fEnf='';const setF=v=>{fEnf=v;$('#pg').innerHTML=page()};
const vazio=c=>`<tr><td colspan="${c}" class="by">${db.pts.length?'Nenhum resultado para a busca.':'Nenhum paciente registrado. Abra um prontuário na aba Prontuários.'}</td></tr>`;

/* ===== DASHBOARD / INÍCIO ===== */
function inicio(){const hoje=new Date().toISOString().slice(0,10),i=db.pts.filter(p=>p.status!=='Óbito'),n=db.pts.filter(p=>p.criado.ts.slice(0,10)===hoje).length,pe=i.filter(p=>!doneNow(p)),al=i.filter(p=>risco(p)==='Alto'),medPend=i.reduce((x,p)=>x+(p.meds||[]).filter(m=>!(m.adm&&m.adm.length)).length,0),medPts=i.filter(p=>(p.meds||[]).some(m=>!(m.adm&&m.adm.length))).length,moder=i.filter(p=>risco(p)==='Moderado').length,baixo=i.filter(p=>risco(p)==='Baixo').length,riscoTotal=al.length+moder+baixo,semRisco=i.length-riscoTotal;
 const prim=p=>esc((p.enfNec||'').split('\\n')[0]),alg=p=>p.alergias?`<span class="alert">${esc(p.alergias)}</span>`:'<span class="by">Nenhuma informada</span>';
 const pct=(v,total)=>total?Math.round(v/total*100):0;
 const medFilter=p=>(p.meds||[]).some(m=>!(m.adm&&m.adm.length));
 if(podeEnf()){const pr=i.filter(p=>!doneNow(p)||risco(p)==='Alto').sort((a,b)=>(RK[risco(b)]||0)-(RK[risco(a)]||0)||doneNow(a)-doneNow(b)||porLeito(a,b));
 return `<div class="dashboard-head"><h1>Olá, ${esc(me.nome)}!</h1><p class="sub">Resumo do turno <b>${turnoDe(Date.now())}</b>. Use os atalhos abaixo para ir direto ao que precisa.</p></div>
 <div class="quick-filters"><button class="quick-filter" onclick="fEnf='';go('pacientes')"><span><strong>Consultar leitos</strong><small>Ver pacientes e leitos</small></span><b>${i.length}</b></button><button class="quick-filter" onclick="fEnf='med';go('enfermagem')"><span><strong>Medicações pendentes</strong><small>${medPend} administrações em ${medPts} pacientes</small></span><b>${medPend}</b></button><button class="quick-filter" onclick="fEnf='pend';go('enfermagem')"><span><strong>Evoluções pendentes</strong><small>Prioridades deste turno</small></span><b>${pe.length}</b></button><button class="quick-filter" onclick="fEnf='alto';go('enfermagem')"><span><strong>Risco alto</strong><small>Pacientes que exigem atenção</small></span><b>${al.length}</b></button><button class="quick-filter" onclick="go('prontuarios')"><span><strong>Prontuários</strong><small>Consultar registros clínicos</small></span><b>›</b></button><button class="quick-filter" onclick="fEnf='';go('enfermagem')"><span><strong>Enfermagem</strong><small>Acompanhamento do turno</small></span><b>›</b></button></div>
 <div class="dashboard-grid"><section class="dashboard-card"><h2>Distribuição de risco</h2><div class="chart-bars"><div class="chart-row"><span>Alto</span><div class="chart-track"><div class="chart-fill danger" style="width:${pct(al.length,riscoTotal)}%"></div></div><b>${al.length}</b></div><div class="chart-row"><span>Moderado</span><div class="chart-track"><div class="chart-fill moderate" style="width:${pct(moder,riscoTotal)}%"></div></div><b>${moder}</b></div><div class="chart-row"><span>Baixo</span><div class="chart-track"><div class="chart-fill" style="width:${pct(baixo,riscoTotal)}%"></div></div><b>${baixo}</b></div></div><p class="by dashboard-chart-note">Base: ${riscoTotal} pacientes com classificação de risco.${semRisco?` ${semRisco} sem classificação.`:''}</p></section><section class="dashboard-card"><h2>Panorama do turno</h2><div class="turno-metrics"><div class="turno-metric"><b>${pe.length}</b><span>Pendências de evolução</span><small>Pacientes sem evolução no turno atual</small></div><div class="turno-metric"><b>${medPend}</b><span>Medicações pendentes</span><small>Administrações ainda não registradas</small></div><div class="turno-metric"><b>${n}</b><span>Novos pacientes hoje</span><small>Prontuários criados hoje</small></div></div></section></div>
 <section class="dashboard-priority"><h2>Prioridades do turno</h2><div class="card tw"><table><tr><th>Leito</th><th>Paciente</th><th>Risco · Observação</th><th>Primeiro cuidado</th><th>Alergias</th><th></th></tr>${pr.map(p=>{const e=lastEnf(p);return `<tr class="lk" onclick="go('enf','${p.id}')"><td><b>${esc(p.leito)}</b></td><td><b>${esc(p.nome)}</b>${demoTag(p)}<div class="by">${age(p.nasc)} anos</div></td><td>${rtag(risco(p))}<div class="by">${esc(e&&e.obs||'')}</div></td><td class="by" style="max-width:280px">${prim(p)}</td><td>${alg(p)}</td><td><button class="btn s">${doneNow(p)?'Ver':'Evoluir'}</button></td></tr>`}).join('')||'<tr><td colspan="6" class="by">Tudo em dia neste turno.</td></tr>'}</table></div></section>
 <div class="dashboard-actions"><button class="btn o" onclick="fEnf='';go('pacientes')">Pacientes</button><button class="btn o" onclick="go('prontuarios')">Prontuários</button><button class="btn o" onclick="go('setembro')">Setembro Amarelo</button></div>`}
 return `<div class="dashboard-head"><h1>Olá, ${esc(me.nome)}!</h1><p class="sub">Resumo do sistema. Consulte rapidamente pacientes, prontuários e alertas sem sobrecarregar a tela inicial.</p></div>
 <div class="quick-filters"><button class="quick-filter" onclick="go('pacientes')"><span><strong>Consultar leitos</strong><small>Ver pacientes e leitos</small></span><b>${i.length}</b></button><button class="quick-filter" onclick="go('prontuarios')"><span><strong>Prontuários</strong><small>Consultar registros clínicos</small></span><b>›</b></button><button class="quick-filter" onclick="fEnf='alto';go('enfermagem')"><span><strong>Alertas e risco alto</strong><small>Pacientes que exigem atenção</small></span><b>${al.length}</b></button><button class="quick-filter" onclick="fEnf='med';go('enfermagem')"><span><strong>Medicações pendentes</strong><small>Administrações ainda não registradas</small></span><b>${medPend}</b></button></div>
 <div class="dashboard-grid"><section class="dashboard-card"><h2>Distribuição de risco</h2><div class="chart-bars"><div class="chart-row"><span>Alto</span><div class="chart-track"><div class="chart-fill danger" style="width:${pct(al.length,riscoTotal)}%"></div></div><b>${al.length}</b></div><div class="chart-row"><span>Moderado</span><div class="chart-track"><div class="chart-fill moderate" style="width:${pct(moder,riscoTotal)}%"></div></div><b>${moder}</b></div><div class="chart-row"><span>Baixo</span><div class="chart-track"><div class="chart-fill" style="width:${pct(baixo,riscoTotal)}%"></div></div><b>${baixo}</b></div></div><p class="by dashboard-chart-note">Base: ${riscoTotal} pacientes com classificação de risco.${semRisco?` ${semRisco} sem classificação.`:''}</p></section><section class="dashboard-card"><h2>Panorama</h2><div class="turno-metrics"><div class="turno-metric"><b>${pe.length}</b><span>Pendências de evolução</span><small>Pacientes sem evolução no turno atual</small></div><div class="turno-metric"><b>${medPend}</b><span>Medicações pendentes</span><small>Administrações ainda não registradas</small></div><div class="turno-metric"><b>${n}</b><span>Novos pacientes hoje</span><small>Prontuários criados hoje</small></div></div></section></div>
 <p class="by dashboard-data-note">Os indicadores acima usam os mesmos prontuários exibidos nas abas Pacientes, Prontuários e Enfermagem; após criar, editar ou administrar uma medicação, os totais são recalculados ao abrir a tela.</p><h2>Risco alto</h2><div class="card tw"><table><tr><th>Leito</th><th>Paciente</th><th>Motivo da internação</th><th>Último registro de enfermagem</th><th></th></tr>${al.sort(porLeito).map(p=>{const e=lastEnf(p);return `<tr class="lk" onclick="go('prontuario','${p.id}')"><td><b>${esc(p.leito)}</b></td><td><b>${esc(p.nome)}</b>${demoTag(p)}<div class="by">${age(p.nasc)} anos</div></td><td>${esc(p.motivo)}</td><td>${e?fmt(e.dh)+' · '+esc(e.turno)+'<div class="by">'+esc(e.texto)+'</div>':'-'}</td><td><button class="btn o s">Abrir prontuário</button></td></tr>`}).join('')||'<tr><td colspan="5" class="by">Nenhum paciente com risco alto no momento.</td></tr>'}</table></div><div class="dashboard-actions"><button class="btn o" onclick="go('pacientes')">Pacientes</button><button class="btn o" onclick="go('prontuarios')">Prontuários</button><button class="btn o" onclick="fEnf='';go('enfermagem')">Enfermagem</button><button class="btn o" onclick="go('setembro')">Setembro Amarelo</button></div>`}

/* Pacientes: só consulta (identificação e leito). Não cria prontuário. */

/* ===== PACIENTES E PRONTUÁRIOS ===== */
function pacientes(){const l=db.pts.filter(achar).sort(porLeito);
  return `<h1>Pacientes</h1><p class="sub">Lista de pacientes da ala · ${db.pts.filter(p=>p.status!=='Óbito').length} internados · ${db.pts.length} registros no total.${' Para abrir um novo prontuário, use a aba <a href="#" onclick="go(\'prontuarios\');return false">Prontuários</a>.'}${isMed()?'':' Toque no paciente para ver o prontuário ou registrar a evolução.'}</p><div class="card tw"><table><tr><th>Leito</th><th>Paciente</th><th>Idade · Sexo</th><th>Alergias</th><th>Status</th><th></th></tr>${l.map(p=>`<tr class="lk" onclick="go('prontuario','${p.id}')"><td><b>${esc(p.leito)}</b></td><td><b>${esc(p.nome)}</b>${demoTag(p)}</td><td>${age(p.nasc)} anos · ${esc(p.sexo)}</td><td class="${p.alergias?'alert':'by'}">${esc(p.alergias||'Nenhuma informada')}</td><td><span class="tag ${p.status==='Óbito'?'x':''}">${esc(p.status)}</span></td><td><button class="btn o s">Abrir prontuário</button></td></tr>`).join('')||vazio(6)}</table></div>`}

/* Prontuários: registros clínicos + criação (consulta a lista de pacientes para evitar duplicidade). */
function prontuarios(){const l=db.pts.filter(achar).sort((a,b)=>new Date(b.criado.ts)-new Date(a.criado.ts)),u=a=>a.length?a.reduce((x,y)=>new Date(y.dh)>new Date(x.dh)?y:x):null;
  return `<h2><span style="font-size:20px">Prontuários</span><button class="btn" onclick="newP()">+ Criar prontuário</button></h2><p class="sub">Registros clínicos: abertura, motivo da internação e evoluções. Ao criar, o sistema consulta a lista de pacientes para evitar registro duplicado.</p><div class="card tw"><table><tr><th>Nº</th><th>Paciente</th><th>Aberto em</th><th>Motivo da internação</th><th>Últ. anotação clínica</th><th>Últ. evolução de enfermagem</th><th>Status</th></tr>${l.map(p=>{const n=u(p.notas||[]),e=lastEnf(p);return `<tr class="lk" onclick="go('prontuario','${p.id}')"><td>${num(p)}</td><td><b>${esc(p.nome)}</b>${demoTag(p)}</td><td>${fmt(p.criado.ts)}<div class="by">${esc(p.criado.by)}</div></td><td>${esc(p.motivo)}</td><td>${n?fmt(n.dh):'-'}</td><td>${e?fmt(e.dh)+' · '+esc(e.turno):'-'}</td><td><span class="tag ${p.status==='Óbito'?'x':''}">${esc(p.status)}</span></td></tr>`}).join('')||vazio(7)}</table></div>`}

/* ---- Evolução de Enfermagem ---- */
function enfermagem(){const at=db.pts.filter(p=>p.status!=='Óbito'),pe=at.filter(p=>!doneNow(p)),al=at.filter(p=>risco(p)==='Alto');
  let l=at.filter(achar);if(fEnf==='pend')l=l.filter(p=>!doneNow(p));if(fEnf==='alto')l=l.filter(p=>risco(p)==='Alto');if(fEnf==='med')l=l.filter(p=>(p.meds||[]).some(m=>!(m.adm&&m.adm.length)));
  l.sort((a,b)=>(RK[risco(b)]||0)-(RK[risco(a)]||0)||doneNow(a)-doneNow(b)||porLeito(a,b));
  const medP=at.reduce((x,p)=>x+(p.meds||[]).filter(m=>!(m.adm&&m.adm.length)).length,0);const medPts=at.filter(p=>(p.meds||[]).some(m=>!(m.adm&&m.adm.length))).length;const ch=(v,t)=>`<button class="chip ${fEnf===v?'on':''}" onclick="setF('${v}')">${t}</button>`;
  return `<h1>Evolução de Enfermagem</h1><p class="sub">Turno atual: <b>${turnoDe(Date.now())}</b> · ${at.length} internados · ${pe.length} sem evolução neste turno</p><div class="chips">${ch('','Todos ('+at.length+')')}${ch('pend','Pendentes no turno ('+pe.length+')')}${ch('alto','Risco alto ('+al.length+')')}${ch('med','Medicações pendentes ('+medP+')')}</div><div class="card tw"><table><tr><th>Leito</th><th>Paciente</th><th>Risco · Observação</th><th>Necessidades de enfermagem</th><th>Último registro</th><th>Turno atual</th><th></th></tr>${l.map(p=>{const e=lastEnf(p);return `<tr class="lk" onclick="go('enf','${p.id}')"><td><b>${esc(p.leito)}</b></td><td><b>${esc(p.nome)}</b>${demoTag(p)}<div class="by">${age(p.nasc)} anos</div></td><td>${rtag(risco(p))}<div class="by">${esc(e&&e.obs||'')}</div></td><td class="by" style="max-width:280px">${esc((p.enfNec||'').split('\n')[0])}</td><td>${e?fmt(e.dh)+'<div class="by">'+esc(e.by)+'</div>':'-'}</td><td><span class="tag ${doneNow(p)?'':'w'}">${doneNow(p)?'Registrado':'Pendente'}</span></td><td><button class="btn s">Evoluir</button></td></tr>`}).join('')||vazio(7)}</table></div>`}

const VL={pa:'PA',fc:'FC',fr:'FR',spo2:'SpO₂',temp:'Temp',dor:'Dor',hgt:'HGT'};
const kv=(k,v)=>v?`<div><span>${k}</span>${esc(v)}</div>`:'';
function evHtml(e){const t=e.vitais||{},vs=Object.keys(VL).filter(k=>t[k]).map(k=>VL[k]+' '+esc(t[k])).join(' · ');
  return `<div class="ev ${esc(e.risco)}"><b>${fmt(e.dh)}</b> <span class="tag g">${esc(e.turno)}</span> ${rtag(e.risco)} ${(e.interc||[]).map(i=>`<span class="tag x">${esc(i)}</span>`).join(' ')}<div class="kv">${kv('Orientação',e.orient)}${kv('Humor/afeto',e.humor)}${kv('Comportamento',(e.aspecto||[]).join(', '))}${kv('Observação',e.obs)}${kv('Riscos',(e.riscos||[]).join(', '))}${kv('Sono',e.sono)}${kv('Alimentação',e.alim)}${kv('Eliminações',e.elim)}${kv('Higiene',e.hig)}${kv('Medicação',e.adesao)}</div>${vs?`<div class="by">Sinais vitais: ${vs}</div>`:''}<p><b>Evolução:</b> ${esc(e.texto)}</p>${e.condutas?`<p><b>Condutas:</b> ${esc(e.condutas)}</p>`:''}${e.plano?`<p><b>Plano p/ próximo turno:</b> ${esc(e.plano)}</p>`:''}<div class="by">Registro: ${esc(e.by)} (${esc(e.reg)}) · ${esc(e.role)}</div></div>`}

function enf(){const p=P();if(!p)return enfermagem();const ob=p.status==='Óbito',ok=podeEnf()&&!ob,v=p.vitais||{},e0=lastEnf(p);
  return `<h2><span style="font-size:20px">Evolução de Enfermagem</span><span><button class="btn o s" onclick="go('enfermagem')">Voltar</button> <button class="btn o s" onclick="go('prontuario')">Ver prontuário</button> <button class="btn s" ${ok?'':'disabled'} onclick="go('enfnova')">+ Nova evolução</button></span></h2><p class="sub">${esc(p.nome)} · Prontuário ${num(p)} · Leito ${esc(p.leito)}</p>${ob?'<div class="ob">Paciente em óbito — registros bloqueados.</div>':''}${podeEnf()?'':'<div class="warn">A evolução de enfermagem é registrada pelo técnico de enfermagem. Seu acesso é de consulta.</div>'}
  <div class="g2"><div><div class="card"><h2>Paciente ${rtag(risco(p))}</h2><div class="kv">${kv('Idade · Sexo',age(p.nasc)+' anos · '+p.sexo)}<div><span>Alergias</span><b class="${p.alergias?'alert':''}">${esc(p.alergias||'Nenhuma informada')}</b></div>${kv('Motivo da internação',p.motivo)}${kv('Observação atual',e0&&e0.obs)}<div><span>Neste turno (${turnoDe(Date.now())})</span>${doneNow(p)?'Registrado':'<b class="alert">Pendente</b>'}</div></div></div>
  <div class="card"><h2>Necessidades e cuidados de enfermagem <button class="btn o s" ${ok?'':'disabled'} onclick="editNec()">Editar</button></h2><div class="need">${esc(p.enfNec||'Nenhuma necessidade especial registrada.')}</div></div>
  <div class="card"><h2>Últimos sinais vitais</h2><div class="vit">${[['PA',v.pa],['FC',v.fc],['FR',v.fr],['SpO₂',v.spo2],['Temp',v.temp],['Dor',v.dor]].map(x=>`<div><span>${x[0]}</span><b>${esc(x[1]||'-')}</b></div>`).join('')}</div><p class="by">${v.ts?fmt(v.ts)+' · '+esc(v.by):'Sem registro'}</p></div></div>
  <div class="card"><h2>Evoluções de enfermagem</h2>${(p.enf||[]).slice().sort((a,b)=>new Date(b.dh)-new Date(a.dh)).map(evHtml).join('')||'<p class="by">Nenhuma evolução de enfermagem registrada.</p>'}</div></div>`}

function editNec(){const p=P();modal(`<form><h2>Necessidades e cuidados de enfermagem</h2><textarea name="nec" rows="8">${esc(p.enfNec||'')}</textarea>${foot}</form>`,d=>{p.enfNec=d.nec.trim();log(p,'Atualizou necessidades de enfermagem');persist(p);view()})}

const OPT={orient:['Orientado no tempo e espaço','Parcialmente orientado','Desorientado'],humor:['Eutímico','Deprimido','Elevado/eufórico','Irritável','Lábil','Embotado/afeto plano','Ansioso'],aspecto:['Calmo/colaborativo','Ansioso','Inquieto/agitado','Hostil','Retraído/isolado','Desconfiado','Choroso','Sonolento'],risco:['Baixo','Moderado','Alto'],riscos:['Suicídio/autolesão','Heteroagressão','Fuga','Queda','Broncoaspiração','Crise convulsiva','Lesão por pressão'],obs:['Rotina','A cada 30 min','A cada 15 min','Contínua (1:1)'],sono:['Dormiu bem','Sono irregular/fragmentado','Insônia','Sonolência excessiva'],alim:['Aceitou toda a dieta','Aceitou parcialmente','Recusou','Dieta assistida'],elim:['Fisiológicas','Constipação','Diarreia','Retenção/dificuldade urinária'],hig:['Autônomo','Com supervisão','Com auxílio parcial','Dependente'],adesao:['Aceitou','Aceitou parcialmente','Recusou','Sem medicação no turno'],interc:['Agitação psicomotora','Heteroagressividade','Autolesão','Tentativa de fuga','Recusa de medicação','Recusa alimentar','Queixa clínica','Queda','Crise convulsiva','Contenção física']};
const sel=(n,l,r)=>`<div><label>${l}${r?' *':''}</label><select name="${n}" ${r?'required':''}><option value="">Selecione</option>${OPT[n].map(o=>`<option>${esc(o)}</option>`).join('')}</select></div>`;
const chk=n=>`<div class="checks">${OPT[n].map(o=>`<label><input type="checkbox" name="${n}" value="${esc(o)}"> ${esc(o)}</label>`).join('')}</div>`;
function enfnova(){const p=P();if(!p||p.status==='Óbito'||!podeEnf())return enf();const v=p.vitais||{},vi=(n,l)=>`<div><label>${l}</label><input name="${n}" placeholder="últ.: ${esc(v[n]||'-')}"></div>`;
  return `<h2><span style="font-size:20px">Nova evolução de enfermagem</span></h2><p class="sub">${esc(p.nome)} · Prontuário ${num(p)} · Leito ${esc(p.leito)}</p>
  <form class="card" onsubmit="return saveEnf(this)"><div class="row"><div><label>Data e hora *</label><input type="datetime-local" name="dh" value="${nowIn()}" required onchange="$('#tn').value=turnoDe(this.value)"></div><div><label>Turno</label><input id="tn" value="${turnoDe(Date.now())}" readonly></div></div><label>Registro de enfermagem</label><input value="${esc(me.nome+' — '+me.reg)}" readonly>
  <div class="sec">Avaliação geral</div><div class="row">${sel('orient','Orientação')}${sel('humor','Humor/afeto')}</div><label>Comportamento observado</label>${chk('aspecto')}
  <div class="sec">Risco e observação</div><div class="row">${sel('risco','Risco atual',1)}${sel('obs','Nível de observação')}</div><label>Tipos de risco identificados</label>${chk('riscos')}
  <div class="sec">Necessidades básicas e medicação</div><div class="row">${sel('sono','Sono')}${sel('alim','Alimentação')}${sel('elim','Eliminações')}${sel('hig','Higiene')}${sel('adesao','Adesão à medicação no turno')}</div>
  <div class="sec">Sinais vitais (opcional — atualiza os sinais vitais do prontuário)</div><div class="vit">${vi('pa','PA')}${vi('fc','FC (bpm)')}${vi('fr','FR (irpm)')}${vi('spo2','SpO₂ (%)')}${vi('temp','Temp (°C)')}${vi('dor','Dor (0-10)')}${vi('hgt','Glicemia capilar (mg/dL)')}</div>
  <div class="sec">Intercorrências</div>${chk('interc')}<p class="by">Contenção física: registrar motivo, horário de início/fim e a prescrição médica no texto.</p>
  <div class="sec">Registro</div><label>Evolução de enfermagem *</label><textarea name="texto" rows="5" required></textarea><label>Condutas e cuidados realizados</label><textarea name="condutas" rows="3"></textarea><label>Plano para o próximo turno (passagem de plantão)</label><textarea name="plano" rows="3"></textarea>
  <div style="display:flex;gap:8px;margin-top:14px"><button class="btn">Registrar evolução</button><button type="button" class="btn o" onclick="go('enf')">Cancelar</button></div></form>`}
function saveEnf(f){if(!podeEnf())return false;const fd=new FormData(f),g=k=>String(fd.get(k)||'').trim(),p=P(),vitais={};
  ['pa','fc','fr','spo2','temp','dor','hgt'].forEach(k=>{if(g(k))vitais[k]=g(k)});
  const e={dh:g('dh'),turno:turnoDe(g('dh')),orient:g('orient'),humor:g('humor'),aspecto:fd.getAll('aspecto'),risco:g('risco'),riscos:fd.getAll('riscos'),obs:g('obs'),sono:g('sono'),alim:g('alim'),elim:g('elim'),hig:g('hig'),adesao:g('adesao'),vitais,interc:fd.getAll('interc'),texto:g('texto'),condutas:g('condutas'),plano:g('plano'),ts:new Date().toISOString(),...who()};
  (p.enf=p.enf||[]).push(e);
  log(p,'Evolução de enfermagem ('+e.turno+') — risco '+e.risco.toLowerCase()+(e.interc.length?' · intercorrências: '+e.interc.join(', '):''));
  if(['pa','fc','fr','spo2','temp','dor'].some(k=>vitais[k])){p.vitais={pa:vitais.pa||'',fc:vitais.fc||'',fr:vitais.fr||'',spo2:vitais.spo2||'',temp:vitais.temp||'',dor:vitais.dor||'',ts:e.ts,...who()};log(p,'Atualizou sinais vitais (evolução de enfermagem)')}
  persist(p);go('enf');return false}

/* ---- Criar prontuário: consulta a lista de pacientes (duplicidade e leito ocupado) ---- */
const tk=s=>norm(s).split(' ').filter(w=>w.length>2);
function dupes(nome,nasc,leito){const m=tk(nome),n=norm(nome),r={exato:[],sim:[],leito:null};
  db.pts.forEach(p=>{const pn=norm(p.nome),c=tk(p.nome).filter(w=>m.includes(w)).length,md=!!nasc&&p.nasc===nasc;if(n&&pn===n&&md)r.exato.push(p);else if(n.length>3&&(pn===n||c>=2||(md&&c>=1)))r.sim.push(p)});
  if(norm(leito))r.leito=db.pts.find(p=>p.status!=='Óbito'&&norm(p.leito)===norm(leito))||null;return r}
function chkDup(){const f=$('#dlg form'),r=dupes(f.nome.value,f.nasc.value,f.leito.value),ok=!!($('#okdup')&&$('#okdup').checked),li=p=>`<div>${esc(p.nome)} · ${fd(p.nasc)} · leito ${esc(p.leito)} · ${esc(p.status)} <button type="button" class="btn s o" onclick="$('#dlg').close();go('prontuario','${p.id}')">Abrir ${num(p)}</button></div>`;let h='',b=false;
  if(r.exato.length){b=true;h+=`<div class="warn bad"><b>Paciente já cadastrado.</b> Abra o prontuário existente em vez de criar outro.${r.exato.map(li).join('')}</div>`}
  if(r.leito){b=true;h+=`<div class="warn bad"><b>Leito ocupado.</b> O leito ${esc(r.leito.leito)} está com ${esc(r.leito.nome)} (${num(r.leito)}).</div>`}
  if(r.sim.length&&!r.exato.length){if(!ok)b=true;h+=`<div class="warn"><b>Possível duplicidade ou homônimo.</b>${r.sim.map(li).join('')}<label style="display:flex;gap:8px;align-items:center;color:var(--tx)"><input type="checkbox" id="okdup" style="width:auto" ${ok?'checked':''}> Confirmo que é outra pessoa</label></div>`}
  $('#dup').innerHTML=h;$('#bsave').disabled=b}
function newP(){modal(`<form><h2>Criar prontuário</h2><p class="by">Informe nome, nascimento e leito: o sistema consulta a lista de pacientes para evitar registro duplicado.</p><label>Nome *</label><input name="nome" required autocomplete="off"><div class="row"><div><label>Sexo *</label><select name="sexo"><option>Feminino</option><option>Masculino</option><option>Outro</option></select></div><div><label>Data de nascimento *</label><input type="date" name="nasc" required></div></div><div class="row"><div><label>Leito *</label><input name="leito" required></div><div><label>Alergias</label><input name="alergias" placeholder="Nenhuma"></div></div><div id="dup"></div><label>Motivo da internação *</label><input name="motivo" required><label>Sinais vitais iniciais</label><div class="row" style="grid-template-columns:repeat(3,1fr)"><input name="pa" placeholder="PA 120/80"><input name="fc" placeholder="FC"><input name="fr" placeholder="FR"><input name="spo2" placeholder="SpO₂"><input name="temp" placeholder="Temp"><input name="dor" placeholder="Dor 0-10"></div><div style="display:flex;gap:8px;margin-top:14px"><button class="btn" id="bsave">Criar prontuário</button><button type="button" class="btn o" data-x>Cancelar</button></div></form>`,d=>{
  const r=dupes(d.nome,d.nasc,d.leito);if(r.exato.length||r.leito)return;
  const ts=new Date().toISOString(),p={id:'p'+Date.now(),nome:d.nome.trim(),sexo:d.sexo,nasc:d.nasc,leito:d.leito.trim(),alergias:d.alergias.trim(),motivo:d.motivo.trim(),status:'Internado',criado:{ts,...who()},notas:[],meds:[],enf:[],enfNec:'',vitais:{pa:d.pa,fc:d.fc,fr:d.fr,spo2:d.spo2,temp:d.temp,dor:d.dor,ts,...who()}};
  db.pts.push(p);pid=p.id;log(p,'Criou o prontuário (motivo: '+p.motivo+')');Promise.resolve(persist(p)).finally(()=>{tab='prontuario';view()})});
  $('#dlg form').addEventListener('input',chkDup);chkDup()}

/* ---- Configurações e pacientes fictícios ---- */
function config(){return `<h1>Configurações</h1><p class="sub">Gerencie seu acesso e dados.</p><div class="card"><h2>${esc(me.nome)}</h2><p class="by">${esc(roleLbl(me.role))} · ${esc(me.reg)}</p><p class="by">Armazenamento: ${!OK()?'neste navegador (localStorage)':'banco de dados MySQL'}</p></div><div class="card"><h2>Pacientes fictícios (demonstração)</h2><p class="by">${db.pts.filter(isDemo).length} pacientes fictícios são carregados automaticamente ao entrar, marcados com DEMO. Cada um tem motivo, necessidades de enfermagem, medicação e evolução próprios. Não use com dados reais.</p></div><div class="card"><h2>Sair do sistema <button class="btn r s" onclick="me=null;pid=null;view()">Sair</button></h2><p class="by">Encerre seu acesso com segurança.</p></div>`}
/* Pacientes fictícios aparecem automaticamente em qualquer login (sem botão de carregar).
   Ficam sempre nas primeiras posições (nº estável); só são gravados no banco se alguém editar o prontuário. */
function ensureDemo(){const ids=new Set(db.pts.map(p=>p.id)),novos=DEMO().filter(d=>!ids.has(d.id)),
 demos=db.pts.filter(isDemo).concat(novos).sort((a,b)=>String(a.id).localeCompare(String(b.id)));
 db.pts=[...demos,...db.pts.filter(p=>!isDemo(p))]}
const MD={by:'Dra. Helena Prado (demo)',reg:'CRM-DEMO 100',role:'Médico'},EQ=[{by:'Téc. Larissa Moura (demo)',reg:'COREN-DEMO 001',role:'Técnico'},{by:'Téc. Bruno Alves (demo)',reg:'COREN-DEMO 002',role:'Técnico'},{by:'Téc. Patrícia Gomes (demo)',reg:'COREN-DEMO 003',role:'Técnico'},{by:'Téc. Rosana Lemos (demo)',reg:'COREN-DEMO 004',role:'Técnico'}];
function DEMO(){const H=36e5,now=Date.now(),y=new Date().getFullYear(),hj=loc(now).slice(5,10),iso=m=>new Date(m).toISOString();
  return SEED.map((s,i)=>{const[nome,sx,idade,md,leito,al,mo,dias,nec,v,meds,nota,e]=s,t0=now-dias*864e5,nu=EQ[i%4],vt={pa:v[0],fc:v[1],fr:v[2],spo2:v[3],temp:v[4],dor:v[5]};
    return{id:'demo'+String(i+1).padStart(2,'0'),nome,sexo:sx==='M'?'Masculino':'Feminino',nasc:(md<=hj?y-idade:y-idade-1)+'-'+md,leito,alergias:al,motivo:mo,status:'Internado',criado:{ts:iso(t0),by:'Dados de demonstração',reg:'FICTÍCIO',role:'Sistema'},enfNec:nec,vitais:{...vt,ts:iso(now-e[0]*H),...nu},
    meds:meds.map(m=>({med:m[0],dose:m[1],via:m[2],hor:m[3],obs:'',ts:iso(t0+H),...MD})),notas:[{dh:loc(t0+2*H),motivo:mo,texto:nota,obito:false,ts:iso(t0+2*H),...MD}],
    enf:[{dh:loc(now-e[0]*H),turno:turnoDe(now-e[0]*H),risco:e[1],obs:e[2],orient:e[3],humor:e[4],sono:e[5],alim:e[6],adesao:e[7],interc:e[8],aspecto:[],riscos:[],texto:e[9],plano:e[10],vitais:vt,ts:iso(now-e[0]*H),...nu}]}})}
const OR='Rotina',O30='A cada 30 min',O15='A cada 15 min',OC='Contínua (1:1)',OT='Orientado no tempo e espaço',OP='Parcialmente orientado',OD='Desorientado',SI='Sono irregular/fragmentado',AT='Aceitou toda a dieta',AP='Aceitou parcialmente',AC='Aceitou';
const SEED=[
['Marcos Antônio Ribeiro','M',34,'03-14','A-01','Dipirona','Episódio maníaco com agitação psicomotora (transtorno bipolar tipo I)',6,'• Ambiente de baixa estimulação; evitar discussões e excesso de visitas\n• Lítio: oferecer 2 L de líquido/dia e observar tremor fino, náuseas e diarreia\n• Sono fragmentado: registrar as horas dormidas a cada manhã',['130/85','92','18','98','36.6','0'],[['Carbonato de lítio','300 mg','VO','8h/14h/20h'],['Olanzapina','10 mg','VO','22h']],'Humor elevado, logorreia e insônia há 5 dias. Contenção verbal eficaz; sem necessidade de contenção física.',[2,'Moderado',O30,OP,'Elevado/eufórico',SI,AP,AC,[],'Falante e dispersivo, aceita orientações após abordagem calma. Dormiu cerca de 4 h. Bebeu pouca água.','Reforçar hidratação; checar tremores antes da dose de lítio da noite.']],
['Helena Cristina Duarte','F',27,'07-22','A-02','Nenhuma conhecida','Depressão grave com ideação suicida estruturada',3,'• Observação contínua 1:1, inclusive no banheiro (porta entreaberta)\n• Revista do quarto e dos pertences a cada turno (retirar cordões e objetos perfurocortantes)\n• Única visita autorizada: a irmã',['100/60','78','16','99','36.4','3'],[['Sertralina','100 mg','VO','8h'],['Clonazepam','0,5 mg','VO','22h']],'Anedonia, desesperança e plano de suicídio relatado na admissão. Plano de segurança pactuado.',[1,'Alto',OC,OT,'Deprimido','Insônia','Recusou',AC,[],'Choro contido, fala pouco; nega planos no momento, mas segue desesperançada. Recusou o almoço; aceitou suco e fruta.','Manter 1:1; oferecer lanche às 15h; avisar a psicologia sobre a recusa alimentar.']],
['João Batista Carvalho','M',71,'11-02','A-03','Penicilina','Delirium sobreposto a demência de Alzheimer',9,'• Alto risco de queda: cama baixa, grades e calçado antiderrapante\n• Acompanhante familiar de dia; reorientar no tempo e espaço a cada contato\n• Óculos e prótese auditiva guardados em estojo identificado à noite\n• Dieta pastosa por disfagia leve, cabeceira elevada',['148/86','84','18','95','36.5','2'],[['Quetiapina','25 mg','VO','20h'],['Donepezila','5 mg','VO','20h']],'Piora da confusão ao entardecer. Fatores clínicos agudos afastados; ambiente ajustado.',[10,'Alto',O30,OD,'',SI,AP,AC,[],'Noite inquieta, tentou levantar sozinho duas vezes; sem queda. Aceitou a dieta pastosa com auxílio.','Manter cama baixa e luz de presença; acompanhante às 7h; reorientar antes do banho.']],
['Luciana Ferreira Matos','F',41,'01-30','A-04','Nenhuma conhecida','Síndrome de abstinência alcoólica — desintoxicação supervisionada',2,'• CIWA-Ar a cada 4 h nas primeiras 72 h; acionar o médico se o escore subir\n• Risco de convulsão: aspirador e O₂ conferidos no início do plantão\n• Tiamina conforme prescrição; dieta fracionada e hipercalórica',['150/95','104','20','97','37.4','2'],[['Diazepam','10 mg','VO','6/6h (esquema decrescente)'],['Tiamina','300 mg','IM','1x/dia'],['Ácido fólico','5 mg','VO','8h']],'Último consumo há 36 h. Tremores, sudorese e ansiedade; sem alucinações.',[3,'Moderado',O30,OT,'Irritável','Insônia',AP,AC,[],'Tremor de extremidades e sudorese leve, CIWA-Ar moderado. Sem crise convulsiva. Queixa de náuseas.','Repetir CIWA-Ar em 4 h; incentivar líquidos; alertar o plantão noturno.']],
['Rafael Augusto Pinheiro','M',22,'09-05','A-05','Látex','Primeiro episódio psicótico com alucinações auditivas',4,'• Alergia a látex: usar luvas e materiais sem látex\n• Abordagem calma, avisando antes de qualquer contato físico\n• Teme envenenamento: abrir a refeição junto com ele\n• Observar rigidez, tremor e sialorreia',['124/78','88','16','99','36.7','0'],[['Risperidona','2 mg','VO','20h'],['Biperideno','2 mg','VO','8h']],'Ouve vozes de comando e acredita ser vigiado. Sem agressividade; colaborativo.',[5,'Moderado',O30,OP,'Embotado/afeto plano',SI,AP,AC,[],'Desconfiado, olha as portas com frequência. Comeu só depois de abrirmos a bandeja juntos. Sem rigidez ou tremor.','Manter abordagem previsível; reavaliar rigidez antes da dose da noite.']],
['Maria das Graças Oliveira','F',58,'05-18','A-06','Sulfa','Depressão maior com sintomas psicóticos e recusa alimentar',12,'• 6 refeições pequenas; registrar a aceitação em % a cada refeição\n• Diabetes tipo 2: glicemia capilar antes das refeições e ao deitar\n• Emagrecimento: inspecionar a pele e pesar 2x/semana',['126/74','80','16','97','36.3','1'],[['Mirtazapina','30 mg','VO','22h'],['Metformina','850 mg','VO','12/12h']],'Acredita estar sendo punida e evita comer. Acompanhamento nutricional; sem sinais de desidratação.',[4,'Moderado',O30,OT,'Deprimido','Dormiu bem',AP,AC,[],'Aceitou cerca de metade do café e do almoço; HGT 132 mg/dL. Verbaliza culpa, aceita conversar com a técnica.','Oferecer lanche às 16h; registrar % aceito; HGT ao deitar.']],
['Davi Lucas Nascimento','M',19,'12-09','A-07','Nenhuma conhecida','Intoxicação por múltiplas substâncias com agitação',1,'• Triagem de pertences e revista de visitas\n• Sinais vitais de 4/4 h na fase aguda; estimular hidratação\n• Fissura: escuta ativa e atividades de distração; encaminhar ao CAPS-AD na alta',['138/88','108','20','98','37.2','1'],[['Diazepam','5 mg','VO','8/8h'],['Haloperidol','5 mg','IM','SOS agitação']],'Trazido por familiares após uso de cannabis sintética e estimulante. Taquicárdico e agitado; melhora gradual.',[2,'Moderado',O30,OP,'Irritável',SI,AC,AC,['Agitação psicomotora'],'Agitação na madrugada, contida com abordagem verbal; sem SOS. Hoje mais calmo, pede para ligar para a mãe.','Repetir sinais vitais em 4 h; autorizar ligação supervisionada.']],
['Teresa Cristina Albuquerque','F',66,'02-27','A-08','AAS (aspirina)','Ansiedade generalizada com pânico e dependência de benzodiazepínico',15,'• Retirada gradual do clonazepam: observar tremor, sudorese e insônia rebote\n• Hipertensão: PA 2x/turno; dieta com pouco sal\n• Crise de pânico: acompanhar respiração diafragmática guiada',['142/88','82','17','98','36.5','2'],[['Clonazepam','1 mg','VO','22h (em redução)'],['Losartana','50 mg','VO','12/12h'],['Escitalopram','10 mg','VO','8h']],'Redução semanal do benzodiazepínico, com insônia rebote; PA levemente elevada.',[8,'Baixo',OR,OT,'Eutímico','Insônia',AT,AC,[],'Relata sono ruim, sem tremores. Crise de pânico breve às 15h, resolvida com respiração guiada. PA 142/88.','Repetir PA às 20h; reforçar higiene do sono.']],
['Pedro Henrique Salgado','M',45,'06-11','A-09','Nenhuma conhecida','Esquizofrenia refratária em uso de clozapina',21,'• Conferir o hemograma semanal (neutrófilos) antes de liberar a clozapina\n• Sialorreia noturna: toalha no travesseiro; registrar evacuações\n• Hipotensão postural: levantar devagar',['118/72','96','16','98','36.6','0'],[['Clozapina','300 mg','VO','22h'],['Lactulose','15 mL','VO','12/12h']],'Sintomas psicóticos residuais controlados. Hemograma da semana sem alterações.',[11,'Baixo',OR,OT,'Eutímico','Dormiu bem',AT,AC,[],'Calmo, participou da oficina de artes. Sem evacuar há 2 dias; sialorreia moderada à noite.','Manter lactulose; estimular água e fibras; checar evacuação amanhã.']],
['Aline Regina Furtado','F',30,'08-16','A-10','Nenhuma conhecida','Transtorno de personalidade borderline com autolesão recorrente',5,'• Inspecionar a pele em todos os banhos e fazer curativos das lesões antigas\n• Plano de segurança por escrito, combinado com a paciente\n• Abordagem consistente entre plantões',['112/70','90','16','99','36.6','4'],[['Lamotrigina','100 mg','VO','8h'],['Quetiapina','50 mg','VO','22h']],'Crise após conflito familiar, com impulsividade e labilidade. Sem lesões novas nas últimas 48 h.',[1,'Alto',O15,OT,'Lábil',SI,AP,AC,[],'Choro e irritação após ligação da família; aceitou conversar com a enfermeira. Pele íntegra no banho.','Manter observação a cada 15 min; avisar a psicologia sobre o impacto da ligação.']],
['Wellington Souza Prado','M',52,'10-03','B-01','Dipirona e contraste iodado','TEPT após acidente de trabalho, com pesadelos e hipervigilância',8,'• Pesadelos: luz de presença; acordar chamando pelo nome, com voz calma\n• Evitar ruídos súbitos e portas batendo\n• Prótese em membro inferior esquerdo: cuidar do coto e prevenir queda',['136/84','90','18','98','36.5','3'],[['Sertralina','150 mg','VO','8h'],['Prazosina','1 mg','VO','22h']],'Revive o acidente em pesadelos; sobressalto a ruídos. Sem ideação suicida.',[9,'Moderado',O30,OT,'Ansioso',SI,AT,AC,[],'Acordou 2x com pesadelo e se acalmou com acolhimento. Coto sem lesões; marcha com prótese estável.','Manter luz de presença; checar o coto no banho.']],
['Sofia Beatriz Lima','F',24,'04-08','B-02','Intolerância à lactose','Anorexia nervosa — reabilitação nutricional supervisionada',14,'• Acompanhar as refeições e a hora seguinte (observar tentativa de purgação); banheiro supervisionado\n• Pesagem em jejum, de costas para a balança, sem informar o valor\n• Conferir os exames de potássio pedidos pela equipe médica',['90/60','54','14','98','35.9','1'],[['Fluoxetina','20 mg','VO','8h'],['Polivitamínico','1 cp','VO','8h']],'Realimentação supervisionada, com ansiedade intensa nas refeições.',[3,'Moderado',O30,OT,'Ansioso','Dormiu bem',AP,AC,[],'Aceitou o almoço com apoio e conversa; tensa ao fim da refeição. Sem tentativa de ir ao banheiro após comer.','Acompanhar o lanche das 16h; repetir PA e FC às 18h.']],
['Francisco das Chagas Moreira','M',63,'03-25','B-03','Carbamazepina (rash cutâneo)','Epilepsia com psicose interictal',18,'• Precauções de convulsão: grades acolchoadas, cama baixa, aspirador e O₂ testados no plantão\n• Registrar tipo, duração e recuperação de qualquer crise\n• Banho acompanhado, sem trancar a porta; evitar privação de sono',['128/80','76','16','97','36.4','0'],[['Valproato de sódio','500 mg','VO','8/8h'],['Risperidona','1 mg','VO','20h']],'Última crise tônico-clônica há 12 dias, antes da internação. Sem alucinações recentes.',[7,'Moderado',O30,OT,'Eutímico','Dormiu bem',AT,AC,[],'Sem crises. Queixa de sonolência leve após o valproato. Banho acompanhado sem intercorrências.','Manter as precauções; checar o aspirador na passagem de plantão.']],
['Camila Rodrigues Azevedo','F',33,'12-01','B-04','Nenhuma conhecida','Depressão pós-parto grave, 9 semanas após o parto',7,'• Lactante: ordenha a cada 3 h em frasco identificado, conforme a orientação médica sobre a medicação\n• Vídeo diário com o bebê, acompanhado pela psicóloga\n• Observar dor e ingurgitamento mamário',['110/68','82','16','99','36.7','2'],[['Sertralina','50 mg','VO','8h']],'Culpa intensa e pensamentos de morte, sem plano atual. Vínculo com o bebê preservado nas visitas.',[2,'Alto',O15,OT,'Deprimido','Insônia',AP,AC,[],'Chorosa após o vídeo com o bebê, mas pediu para repeti-lo amanhã. Ordenha às 12h e 15h; mama direita com leve ingurgitamento.','Compressa morna antes da ordenha; manter 15 min; avisar a psicologia.']],
['Otávio Miranda Teixeira','M',80,'07-14','B-05','Dipirona','Depressão em idoso com DPOC',10,'• DPOC: O₂ por cateter nasal a 2 L/min se SpO₂ < 90% (conforme prescrição); cabeceira a 30°\n• SpO₂ a cada 4 h; nebulização de 6/6h\n• Evitar benzodiazepínicos; risco de queda',['140/80','88','22','91','36.4','3'],[['Escitalopram','10 mg','VO','8h'],['Ipratrópio','20 gotas','Nebulização','6/6h']],'Humor deprimido e pouca energia; dispneia aos pequenos esforços, estável em ar ambiente.',[6,'Moderado',O30,OT,'Deprimido','Dormiu bem',AP,AC,[],'SpO₂ 91% em ar ambiente, sem necessidade de O₂. Cansa ao caminhar até o refeitório. Aceitou as nebulizações.','Repetir SpO₂ às 18h; acompanhar até o refeitório.']],
['Jéssica Monteiro Barreto','F',29,'05-30','B-06','Nenhuma conhecida','Surto psicótico breve em gestante de 28 semanas',4,'• Gestante: avaliar movimentos fetais e BCF a cada turno\n• Decúbito lateral esquerdo; observar edema e PA (pré-eclâmpsia)\n• Medicações conforme avaliação obstétrica; manter o pré-natal',['118/72','96','20','98','36.7','1'],[['Haloperidol','2,5 mg','VO','12/12h'],['Sulfato ferroso','40 mg','VO','12h'],['Ácido fólico','5 mg','VO','8h']],'Delírio de conteúdo religioso com insônia. Obstetrícia: gestação sem intercorrências.',[3,'Moderado',O30,OP,'Ansioso',SI,AT,AC,[],'Refere movimentos fetais presentes; BCF 142 bpm. Sem edema. Menos agitada, ainda com ideias delirantes.','Repetir BCF no próximo turno; manter decúbito lateral esquerdo.']],
['Ibrahim Diallo','M',38,'09-19','B-07','Nenhuma conhecida','Psicose reativa em refugiado, com barreira de idioma',6,'• Fala francês e árabe: cartões ilustrados e intérprete por telefone\n• Dieta halal; reservar espaço e horários de oração\n• Explicar cada procedimento passo a passo antes de realizar',['122/76','80','16','99','36.6','0'],[['Olanzapina','5 mg','VO','22h']],'Desorganização do pensamento após perda de familiares no deslocamento. Avaliação feita com intérprete.',[12,'Baixo',OR,OP,'Embotado/afeto plano','Dormiu bem',AT,AC,[],'Colaborativo com os cartões ilustrados. Aceitou a dieta halal e usou o espaço de oração.','Solicitar intérprete para a visita médica de amanhã.']],
['Beatriz Helena Carvalho','F',21,'02-12','B-08','Amendoim (anafilaxia)','Crise de desorganização em transtorno do espectro autista',3,'• Alergia grave a amendoim: conferir toda bandeja; adrenalina acessível na sala de enfermagem\n• Sensibilidade sensorial: quarto individual, pouca luz, fone abafador\n• Frases curtas e pictogramas; avisar mudanças de rotina com antecedência\n• Aceita apenas alimentos macios; mãe como acompanhante integral',['112/70','86','16','99','36.5','1'],[['Aripiprazol','5 mg','VO','8h']],'Desorganização após mudança de ambiente, com autoestimulação intensa. Melhora com menos estímulos.',[4,'Baixo',OR,OT,'Ansioso','Dormiu bem',AP,AC,[],'Sem crises hoje. Usou os pictogramas para pedir água e banho. Recusou a salada; aceitou purê e frutas.','Avisar o horário do banho com pictograma; conferir as bandejas.']],
['Genivaldo Pires Cavalcante','M',49,'11-23','B-09','Contraste iodado','Transtorno bipolar em fase depressiva com doença renal crônica em hemodiálise',11,'• Hemodiálise 2ª/4ª/6ª: transporte e retorno acompanhados\n• Fístula no braço esquerdo: sem punção nem PA nesse braço\n• Restrição hídrica e dieta renal (pouco potássio e fósforo)\n• Doses ajustadas à função renal; lítio contraindicado',['150/90','78','18','96','36.3','2'],[['Quetiapina','100 mg','VO','22h'],['Carbonato de cálcio','500 mg','VO','com as refeições']],'Humor deprimido, boa adesão à hemodiálise. Psiquiatria e nefrologia alinharam as doses.',[5,'Moderado',O30,OT,'Deprimido','Dormiu bem',AP,AC,[],'Voltou da hemodiálise sem intercorrências, cansado. PA aferida no braço direito. Respeitou a restrição hídrica.','Pesar após a hemodiálise; reforçar a restrição de líquidos.']],
['Raimunda Nonata Silva','F',74,'06-06','B-10','Nenhuma conhecida','Depressão com ideação de morte após viuvez, sem rede de apoio',16,'• Lesão por pressão estágio 1 na região sacra: mudar de decúbito a cada 2 h; colchão piramidal\n• Sem familiares: assistente social buscando contatos\n• Estimular a oficina de música e o contato social',['134/78','74','16','97','36.2','2'],[['Sertralina','50 mg','VO','8h'],['Suplemento hipercalórico','200 mL','VO','2x/dia']],'Luto recente e isolamento. Hiperemia sacra não branqueável, tratada com mudança de decúbito.',[3,'Moderado',O30,OT,'Deprimido',SI,AP,AC,[],'Hiperemia sacra estável, sem abertura de pele. Participou da oficina de música e sorriu ao cantar. Verbaliza solidão.','Mudança de decúbito a cada 2 h; avisar a assistente social sobre o contato da sobrinha.']]
];

/* ========= ACESSIBILIDADE ========= */
const A11=(()=>{
 const KEY='prontuario_a11y_prefs',H=document.documentElement,DEF={dyslexic:'off',underline:'off',cursor:'off',grayscale:'off',spacing:'off',vlibras:'off',speak:'off'};
 let prefs=(()=>{try{return{...DEF,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch(e){return{...DEF}}})(),started=false,utt=null,tok=0;
 const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(prefs))}catch(e){}};
 const isLogged=()=>!!me;
 const syncSwitches=()=>document.querySelectorAll('[data-a11y-switch]').forEach(b=>b.setAttribute('aria-pressed',String(prefs[b.dataset.a11ySwitch]==='on')));
 function buildVL(){const w=document.createElement('div');w.setAttribute('vw','');w.className='enabled';w.id='vlibras-wrapper';w.innerHTML='<div vw-access-button class="active"></div><div vw-plugin-wrapper><div class="vw-plugin-top-wrapper"></div></div>';document.body.appendChild(w)}
 function initVL(){if(!window.VLibras||started)return;new window.VLibras.Widget('https://vlibras.gov.br/app');started=true}
 function loadVL(){H.setAttribute('data-a11y-vlibras','on');if(started)return;if(!document.getElementById('vlibras-wrapper'))buildVL();if(document.getElementById('vlibras-script')){initVL();return}const sc=document.createElement('script');sc.id='vlibras-script';sc.src='https://vlibras.gov.br/app/vlibras-plugin.js';sc.onload=()=>{if(prefs.vlibras==='on')initVL()};document.body.appendChild(sc)}
 function setSpeakVisibility(){const b=document.getElementById('a11y-fab');const show=isLogged()&&prefs.speak==='on';if(b)b.hidden=!show;if(!show)stop()}
 function apply(){['dyslexic','underline','cursor','grayscale','spacing'].forEach(k=>H.setAttribute('data-a11y-'+k,prefs[k]));syncSwitches();if(prefs.vlibras==='on')loadVL();else H.setAttribute('data-a11y-vlibras','off');setSpeakVisibility()}
 function text(){const sel=String(getSelection?getSelection():'').trim();if(sel.length>3)return sel;const el=$('#pg');return el?el.innerText.trim():''}
 function setSpeakBtn(v){const b=document.getElementById('a11y-fab');if(b){b.setAttribute('aria-pressed',String(v));b.setAttribute('aria-label',v?'Parar leitura':'Ler esta página em voz alta')}}
 function stop(){tok++;if('speechSynthesis'in window)speechSynthesis.cancel();setSpeakBtn(false)}
 function chunks(t){const out=[];String(t).replace(/\s+/g,' ').split(/(?<=[.!?;:])\s+/).forEach(s=>{while(s.length>180){let i=s.lastIndexOf(' ',180);if(i<60)i=180;out.push(s.slice(0,i));s=s.slice(i).trim()}if(s)out.push(s)});return out}
 function speak(){if(!isLogged()||prefs.speak!=='on')return;if(!('speechSynthesis'in window)){alert('Seu navegador não suporta leitura em voz alta.');return}stop();const t=text();if(!t)return;const my=++tok,q=chunks(t),vs=speechSynthesis.getVoices(),v=vs.find(x=>/^pt[-_]BR/i.test(x.lang))||vs.find(x=>/^pt/i.test(x.lang));setSpeakBtn(true);let i=0;const next=()=>{if(my!==tok)return;if(i>=q.length){setSpeakBtn(false);return}utt=new SpeechSynthesisUtterance(q[i++]);utt.lang='pt-BR';if(v)utt.voice=v;utt.rate=1;utt.onend=next;utt.onerror=e=>{if(e.error==='interrupted'||e.error==='canceled')return;next()};speechSynthesis.speak(utt)};next()}
 function toggle(){const b=document.getElementById('a11y-fab');if(b&&b.getAttribute('aria-pressed')==='true')stop();else speak()}
 function fab(){let b=document.getElementById('a11y-fab');if(b){setSpeakVisibility();return}b=document.createElement('button');b.id='a11y-fab';b.type='button';b.className='fab';b.hidden=true;b.setAttribute('aria-pressed','false');b.setAttribute('aria-label','Ler esta página em voz alta');b.title='Ler esta página em voz alta';b.innerHTML='<svg class="ico-play" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9 9 0 0 1 0 13"/></svg><svg class="ico-stop" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="6" y="6" width="12" height="12" rx="2"/></svg><span>Ouvir</span>';b.onclick=toggle;document.body.appendChild(b);setSpeakVisibility()}
 window.addEventListener('pagehide',stop);
 return{
  on:k=>prefs[k]==='on',
  toggle(k){prefs[k]=prefs[k]==='on'?'off':'on';save();apply()},
  reset(){prefs={...DEF};save();stop();apply()},
  speak,stop,apply,fab,syncFab:setSpeakVisibility
 }})();
A11.apply();A11.fab();
function acess(){
 const sw=(k,t,l,d)=>`<div class="a11y-row"><div><span>${t}</span>${d?`<small>${d}</small>`:''}</div><button class="a11y-sw" type="button" data-a11y-switch="${k}" aria-pressed="${A11.on(k)}" aria-label="${l}" onclick="A11.toggle('${k}')"></button></div>`;
 return `<h1>Acessibilidade</h1><p class="sub">Ajustes de leitura e navegação. Ficam salvos neste navegador e valem para todas as telas.</p><div class="a11y-list">
${sw('dyslexic','Fonte para dislexia','Ativar fonte OpenDyslexic')}
${sw('underline','Sublinhar links','Sublinhar links')}
${sw('cursor','Cursor ampliado','Ativar cursor ampliado')}
${sw('grayscale','Escala de cinza','Ativar escala de cinza')}
${sw('spacing','Espaçamento de texto','Aumentar espaçamento de texto')}
${sw('vlibras','VLibras (Libras)','Ativar tradutor de Libras','Carrega o tradutor do Governo Federal (vlibras.gov.br) e envia o texto traduzido a esse serviço. Evite com dados reais de pacientes.')}
${sw('speak','Leitura em voz alta','Exibir o botão "Ouvir" nas telas do sistema','Quando ativado, o botão flutuante de leitura aparece somente após o login.')}
<button class="a11y-reset" type="button" onclick="A11.reset()">Restaurar padrões</button></div>`}

view();
